loop_actions.code:
const renewalDate = new Date(inputData.renewal_date);
const today = new Date();
const daysUntil = Math.ceil((renewalDate - today) / (1000 * 60 * 60 * 24));

let stage = '';
let actions = [];
let priority = 'low';

if (daysUntil <= 30) {
  stage = 'critical';
  priority = 'urgent';
  actions = ['Send renewal contract', 'Schedule signature call', 'Executive check-in'];
} else if (daysUntil <= 60) {
  stage = 'active_renewal';
  priority = 'high';
  actions = ['Present renewal proposal', 'Discuss expansion opportunities', 'Address concerns'];
} else if (daysUntil <= 90) {
  stage = 'pre_renewal';
  priority = 'medium';
  actions = ['Schedule renewal planning call', 'Gather usage data', 'Prepare proposal'];
} else {
  stage = 'early_planning';
  priority = 'low';
  actions = ['Monitor health score', 'Track feature requests', 'Build relationship'];
}

return {
  client_id: inputData.id,
  client_name: inputData.name,
  days_until_renewal: daysUntil,
  renewal_stage: stage,
  priority: priority,
  recommended_actions: actions,
  contract_value: inputData.contract_value,
  health_score: inputData.health_score || 75
};

